// Kotlin/Wasm >= JS adapter for the C0b spike.
//
// Kotlin/Wasm cannot `fetch()`/`instantiateStreaming()` a .wasm file by itself and
// webpack rewrites `new URL(..., import.meta.url)`, so the module is embedded as
// base64 (generated by protocol-wasm/build.sh) and instantiated once here.
//
// Everything else is a pass-through: the protocol core stays in Rust, the
// transport stays in the host (WebSocket in JS), and Kotlin only ever sees
// Promise / Uint8Array / callback — the same surface C-10 will have to bind.

import init, {
  handshake as wasmHandshake,
  encrypt as wasmEncrypt,
  decrypt as wasmDecrypt,
  on_event,
  Peer,
  Role,
} from 'protocol-wasm';
import { WASM_BASE64 } from 'protocol-wasm/wasm-b64.js';
import { WebSocketServer } from 'ws';

let ready = null;

function ensure() {
  if (ready === null) {
    const bin = atob(WASM_BASE64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
    ready = init({ module_or_path: bytes });
  }
  return ready;
}

export async function load() {
  await ensure();
  return true;
}

export async function handshake(transport, pskHex) {
  await ensure();
  return wasmHandshake(transport, pskHex ?? undefined);
}

export async function encrypt(bytes) {
  await ensure();
  return wasmEncrypt(bytes);
}

export async function decrypt(bytes) {
  await ensure();
  return wasmDecrypt(bytes);
}

export async function onEvent(cb) {
  await ensure();
  on_event(cb);
}

export function textEncode(text) {
  return new TextEncoder().encode(text);
}

export function textDecode(bytes) {
  return new TextDecoder().decode(bytes);
}

export function asText(value) {
  return String(value);
}

// ---- host side of the transport: exactly the object T2 asks the host to provide ----

export async function makeTransport(url, remoteStaticKeyHex) {
  const ws = new WebSocket(url);
  const inbox = [];
  const waiters = [];

  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });

  ws.addEventListener('message', (event) => {
    const bytes = new Uint8Array(event.data);
    if (waiters.length) waiters.shift()(bytes);
    else inbox.push(bytes);
  });

  const key = new Uint8Array(remoteStaticKeyHex.length / 2);
  for (let i = 0; i < key.length; i += 1) {
    key[i] = parseInt(remoteStaticKeyHex.slice(i * 2, i * 2 + 2), 16);
  }

  return {
    remoteStaticKey: () => key,
    send: (bytes) => ws.send(bytes),
    recv: () =>
      new Promise((resolve, reject) => {
        if (inbox.length) return resolve(inbox.shift());
        const timer = setTimeout(() => reject(new Error('recv timeout')), 5000);
        waiters.push((b) => {
          clearTimeout(timer);
          resolve(b);
        });
      }),
    close: () => ws.close(),
  };
}

export async function exchange(transport, bytes) {
  transport.send(bytes);
  return transport.recv();
}

// ---- test scaffolding: the "core" side of the socket, same wasm module ----

export async function startEchoServer(pskHex) {
  await ensure();
  const responder = new Peer(Role.Responder, undefined, pskHex);
  const wss = new WebSocketServer({ host: '127.0.0.1', port: 0 });
  await new Promise((resolve) => wss.once('listening', resolve));

  wss.on('connection', (ws) => {
    ws.on('message', (data) => {
      const bytes = new Uint8Array(data);
      if (!responder.is_established()) {
        responder.read_handshake(bytes);
        if (!responder.is_established()) ws.send(responder.write_handshake());
        return;
      }
      ws.send(responder.encrypt(responder.decrypt(bytes)));
    });
  });

  return {
    url: `ws://127.0.0.1:${wss.address().port}`,
    responderPub: responder.static_public_key_hex(),
    pskHex,
    close: () => wss.close(),
  };
}
